int git_index_read_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    const git_index_entry *entry = (const git_index_entry *)buffer;

    if (buffer_size < sizeof(git_index_entry)) {
        return -1; /* Buffer is too small */
    }

    *out_size = sizeof(git_index_entry);

    /* Allocate a new index entry */
    *out = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!*out) {
        return -1; /* Allocation failed */
    }

    /* Copy the entry data */
    memcpy(*out, entry, sizeof(git_index_entry));

    /* Handle path reconstruction if needed */
    if (last && strlen(last) > 0) {
        size_t path_len = strlen(entry->path) + strlen(last) + 2;
        char *full_path = (char *)malloc(path_len);
        if (!full_path) {
            free(*out);
            return -1; /* Allocation failed */
        }
        snprintf(full_path, path_len, "%s/%s", entry->path, last);
        free((*out)->path); /* Free the old path if it was allocated */
        (*out)->path = full_path;
    } else {
        /* Copy path directly if last is empty or not provided */
        size_t path_len = strlen(entry->path) + 1;
        (*out)->path = (char *)malloc(path_len);
        if (!(*out)->path) {
            free(*out);
            return -1; /* Allocation failed */
        }
        memcpy((void *)(*out)->path, entry->path, path_len);
    }

    return 0; /* Success */
}

int git_index_entry_from_buffer(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
	if (buffer_size < sizeof(git_index_entry))
		return -1;

	git_index_entry *entry = (git_index_entry *)malloc(sizeof(git_index_entry));
	if (!entry)
		return -1;

	memcpy(entry, buffer, sizeof(git_index_entry));

	char *path = NULL;
	if (entry->path_len) {
		path = (char *)malloc(entry->path_len + 1);
		if (!path) {
			free(entry);
			return -1;
		}

		if (last) {
			snprintf(path, entry->path_len + 1, "%s/%s", last, entry->path);
		} else {
			strncpy(path, entry->path, entry->path_len);
			path[entry->path_len] = '\0';
		}
	}

	entry->path = path;
	*out = entry;
	*out_size = sizeof(git_index_entry);
	return 0;
}

int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));

    const char *path;
    if (entry->flags_extended & GIT_INDEX_ENTRY_FLAG_CASE) {
        path = git_index_entry_raw_path(entry);
    } else {
        size_t path_len = strlen(last) + 1;
        path = malloc(path_len);
        if (!path) {
            free(entry);
            return -1;
        }
        snprintf((char *)path, path_len, "%s", last);
        entry->path = path;
    }

    *out = entry;
    *out_size = sizeof(git_index_entry);

    return 0;
}

